<?php defined('BASEPATH') OR exit('No direct script access allowed'); ?>
<h1 class="h4 mb-3">Pesanan</h1>
<?php if ($this->session->flashdata('success')): ?><div class="alert alert-success py-2"><?php echo html_escape($this->session->flashdata('success')); ?></div><?php endif; ?><?php if ($this->session->flashdata('error')): ?><div class="alert alert-danger py-2"><?php echo html_escape($this->session->flashdata('error')); ?></div><?php endif; ?>
<div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>Nomor</th><th>Pelanggan</th><th>Status</th><th>Total</th><th>Tanggal</th><th>Aksi</th></tr></thead><tbody><?php foreach ($orders as $order): ?><tr><td><?php echo html_escape($order->order_number); ?></td><td><?php echo html_escape($order->customer_name); ?></td><td><?php echo html_escape($order->status); ?></td><td>Rp <?php echo number_format((float)$order->total,0,',','.'); ?></td><td><?php echo html_escape($order->created_at); ?></td><td><?php if ($order->status !== 'cancelled' && $order->status !== 'delivered'): ?><form method="post" action="<?php echo site_url('admin/orders/cancel/'.$order->id); ?>" onsubmit="return confirm('Batalkan pesanan dan lepaskan stok reservasi?');"><input type="hidden" name="<?php echo $this->security->get_csrf_token_name(); ?>" value="<?php echo $this->security->get_csrf_hash(); ?>"><button class="btn btn-sm btn-outline-danger" type="submit">Batalkan</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
